const ELEMENTS = ['none', 'water', 'earth', 'fire', 'wind', 'poison', 'holy', 'shadow', 'ghost', 'undead'];
const ELEMENT_NAMES = {
  none: '無', water: '水', earth: '地', fire: '火', wind: '風',
  poison: '毒', holy: '聖', shadow: '暗', ghost: '念', undead: '不死'
};
